SourceCode.Declaration:
class MwmsLogicStepOperatorOnHand extends TFMLogicBlock implements TFMLogicStepOperatorInterface
{

    InventSum					  inventSum;

}

Method.Source:
public str runLogic ( TFMRequestElement _request )
{
    TFMRequestItemAndDimensionElement   requestItemAndDim = _request.convertToOtherRequestType(classStr(TFMRequestItemAndDimensionElement));
    ItemId                              itemId = requestItemAndDim.parmItemId();          
    InventDim                           inventDim = requestItemAndDim.parmInventDim();
    InventDimParm                       inventDimParm;

    inventDimParm.initFromInventDim(inventDim);
    inventSum = InventSum::findSum(itemId, inventDim, inventDimParm);
    _request.logicContext().addDataContext(inventSum, this.blockName());
    return '';
}
